MOTIF_NAME = 'stm_fewer_pawn_islands'
MOTIF_DESCRIPTION = 'Side to move has fewer pawn islands than the opponent, indicating better pawn structure.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    def count_islands(color):
        files = [False] * 8
        for sq in board.pieces(chess.PAWN, color):
            files[chess.square_file(sq)] = True
        count = 0
        for i in range(8):
            if files[i] and (i == 0 or not files[i-1]):
                count += 1
        return count

    return count_islands(stm) < count_islands(opp)

MOTIF_NAME = 'piece_in_enemy_territory'
MOTIF_DESCRIPTION = 'Side to move has at least one piece positioned on the opponent half of the board (ranks 4-7 for White, ranks 0-3 for Black).'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    for piece_type in [chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN, chess.KING]:
        for sq in board.pieces(piece_type, stm):
            rank = chess.square_rank(sq)
            if stm:
                if rank >= 4:
                    return True
            else:
                if rank <= 3:
                    return True
    return False

MOTIF_NAME = 'major_piece_coordination'
MOTIF_DESCRIPTION = 'Side to move has more major pieces (rooks and queen) with at least one defender than the opponent.'

def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    def count_defended_major(color):
        count = 0
        for sq in board.pieces(chess.ROOK, color):
            if board.attackers(color, sq):
                count += 1
        for sq in board.pieces(chess.QUEEN, color):
            if board.attackers(color, sq):
                count += 1
        return count

    return count_defended_major(stm) > count_defended_major(opp)

MOTIF_NAME = 'minor_piece_development'
MOTIF_DESCRIPTION = 'Side to move has at least 3 of 4 minor pieces developed off starting squares.'
def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    if stm:
        starting_squares = {chess.B1, chess.G1, chess.C1, chess.F1}
    else:
        starting_squares = {chess.B8, chess.G8, chess.C8, chess.F8}
    developed = 0
    for piece_type in [chess.KNIGHT, chess.BISHOP]:
        for sq in board.pieces(piece_type, stm):
            if sq not in starting_squares:
                developed += 1
    return developed >= 3

import chess

MOTIF_NAME = 'queen_centralized'
MOTIF_DESCRIPTION = 'Side to move has queen on or attacking central squares d4, d5, e4, e5.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn

    central_squares = [chess.square(3, 3), chess.square(3, 4), chess.square(4, 3), chess.square(4, 4)]

    queen_squares = list(board.pieces(chess.QUEEN, stm))
    if not queen_squares:
        return False

    for sq in queen_squares:
        if sq in central_squares:
            return True

    for sq in queen_squares:
        attacks = board.attacks(sq)
        for cs in central_squares:
            if cs in attacks:
                return True

    return False

MOTIF_NAME = 'centralized_knight'
MOTIF_DESCRIPTION = 'Side to move has a knight on one of the four central squares (d4, d5, e4, e5)'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn

    central_squares = [chess.D4, chess.D5, chess.E4, chess.E5]

    for sq in board.pieces(chess.KNIGHT, stm):
        if sq in central_squares:
            return True
    return False

import chess

MOTIF_NAME = 'piece_fork_potential'
MOTIF_DESCRIPTION = 'Side to move has a piece attacking two or more opponent pieces.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    piece_types = [chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN]

    for piece_type in piece_types:
        for sq in board.pieces(piece_type, stm):
            attacks = board.attacks(sq)
            count = 0
            for attack_sq in attacks:
                piece = board.piece_at(attack_sq)
                if piece and piece.color == opp:
                    count += 1
            if count >= 2:
                return True

    return False
